import{Ct as e,ct as t,lt as n,q as r}from"./chunks/framework.BVmwMUcr.js";import"./chunks/assets.BR0KDKWk.js";var i=JSON.parse(`{"title":"转信工经验分享（2026）","description":"华南理工大学转专业至电子与信息学院（信息工程专业）的经验分享，含笔试内容、面试标准与备考建议","frontmatter":{"lang":"zh-CN","title":"转信工经验分享（2026）","description":"华南理工大学转专业至电子与信息学院（信息工程专业）的经验分享，含笔试内容、面试标准与备考建议","date":"2026-07-26T00:00:00.000Z","author":"fish152363","sidebarDepth":2},"headers":[],"relativePath":"learn/curricular/transfer_major_information_engineering_fish_2026.md","filePath":"learn/curricular/transfer_major_information_engineering_fish_2026.md","lastUpdated":1785119564000}`),a={name:`learn/curricular/transfer_major_information_engineering_fish_2026.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /learn/curricular/transfer_major_information_engineering_fish_2026.md for this page in Markdown format</div><h1 id="信工转专业经验谈" tabindex="-1">信工转专业经验谈 <a class="header-anchor" href="#信工转专业经验谈" aria-label="Permalink to “信工转专业经验谈”">​</a></h1><p>（电信转专业群号：1037507331）</p><p>一，选择</p><p>大家既然点开了这篇文章，那么我便开门见山：</p><p>如果大家觉得可以接受原专业，那么可以适当冲击竞争压力大的热门工科专业（计软信自电＋机电），这些热门工科报录比一般都很高，竞争压力大，失败风险更高。</p><p>如果大家无法接受原专业，原专业情况实在太差，那么大家应该酌情考虑自身情况来抉择，虽然热门工科确实发展更好，但是失败率确实更高，可以看一下其他工科（能动材料等），先保证能跑掉，大一跑不掉无论是大二降转还是跨考压力都会更大。</p><p>当然，如何抉择风险与收益，大家可以根据自身情况判断。</p><p>概况：</p><p>电信转专业接受情况如下：</p><p>其他事项提醒：</p><p>25届因为报名人数不够未开设中法班，但是26届中法班仍有招生计划，详细内容可进电信转专业群询问。</p><p>三，流程</p><p>大致流程如下：</p><p>其他事项提醒：</p><p>报名人数可在转专业报名页面看到（仅限报名前，报名后看不到，转专业群如果有群友统计，可在转专业群看）</p><p>四，具体准备</p><p>信工转专业分为笔试和面试：</p><p>笔试（大一下5.7左右）要求如图</p><p>准备工作分配：</p><p>大一上主要准备就是尽量提高高数，线代以及总绩点。</p><p>在大一寒假可以适当保持高数和线代手感）</p><p>在大二下主要认真学高数下和大物（其他主课如概率论也别全部放，不然期末就要遭罪）大概在4月中就可以开始刷题（大物，线代，高数）</p><p>一般老师都能在转专业笔试前讲完转专业的考试范围内的课程，但是那时复习和刷题的时间可能不够，所以还是建议提前预习留够时间</p><p>考试内容提醒:</p><p>25届笔试高数和大物出题中规中矩，刷往年题目即可。</p><p>但是线代考的很难，比期末难度有过之而无不及，大题也没有什么正定矩阵的套路题目，而是出了一道压轴证明题，难以给出复习策略，正常看一下即可</p><p>其他事项提醒：</p><p>信工笔试允许带计算器，建议直接买一个卡西欧计算器，期末大物考试也要用。(线代大物有些题可能要用计算器)</p><p>面试（笔试过后大概一周）：</p><p>要求如图：</p><p>准备工作分配：</p><p>考完笔试大概有不到一星期时间准备面试，自我介绍部分可以介绍自己的一些学习方法，参加的srp项目等等，根据自己的情况写即可（四级分数和高考分数省排可以写一下，好像问的挺多）。</p><p>老师提问会根据你的自我介绍来问，当时问了笔者srp项目和一些爱好。面试更多i的是个人临场思考能力，放松自然作答即可。</p><p>其他事项提醒：</p><p>面试当天是要去五山校区，可以坐地铁，校巴或者打车，如图：</p><p>五．结语</p><p>当你看完本文，不论是结合自身情况决定转其他专业还是坚定了转电信的目标，笔者都真诚地祝福你成功。大家转专业可能都有自己的难言之隐，这个夏天可能不那么美好。但是你还是看完了本文，希望能为故事写下一个完美的句号。那就种下一棵种子吧，期待一年后的硕果———这篇文章便是我的硕果。</p><p>祝各位转专业顺利，前途似锦！</p><h2 id="图片资料" tabindex="-1">图片资料 <a class="header-anchor" href="#图片资料" aria-label="Permalink to “图片资料”">​</a></h2><p><img src="/root-assets/transfer_major/InformationEngineering_fish_2026/images/image1.png" alt="图片1"></p><p><img src="/root-assets/transfer_major/InformationEngineering_fish_2026/images/image2.png" alt="图片2"></p><p><img src="/root-assets/transfer_major/InformationEngineering_fish_2026/images/image3.png" alt="图片3"></p><p><img src="/root-assets/transfer_major/InformationEngineering_fish_2026/images/image4.png" alt="图片4"></p><p><img src="/root-assets/transfer_major/InformationEngineering_fish_2026/images/image5.png" alt="图片5"></p>`,45)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};